add_filter( 'all_plugins', 'perfectpixel_active_plugins_first', 999 );

function perfectpixel_active_plugins_first( $plugins ) {
	if ( ! is_admin() || ! function_exists( 'is_plugin_active' ) ) {
		return $plugins;
	}
	$active   = array();
	$inactive = array();
	foreach ( (array) $plugins as $file => $data ) {
		if ( is_plugin_active( $file ) ) {
			$active[ $file ] = $data;
		} else {
			$inactive[ $file ] = $data;
		}
	}
	return $active + $inactive;
}
